import{_ as l,C as c,o as n,c as h,j as t,a,E as e,aj as r}from"./chunks/framework.DkvuVDKz.js";const k=JSON.parse('{"title":"BarCode 条形码","description":"","frontmatter":{},"headers":[],"relativePath":"components/bar-code.md","filePath":"components/bar-code.md","lastUpdated":1789424204000}'),s={name:"components/bar-code.md"},b={id:"barcode-条形码",tabindex:"-1"};function u(p,d,m,f,x,g){const i=c("Badge"),o=c("XhDemo");return n(),h("div",null,[t("h1",b,[d[0]||(d[0]=a("BarCode 条形码 ",-1)),e(i,{type:"info",text:"alpha"}),d[1]||(d[1]=a()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#barcode-条形码","aria-label":'Permalink to "BarCode 条形码 <Badge type="info" text="alpha" />"'},"​",-1))]),d[3]||(d[3]=r('<p>把一段文本画成一维条形码，<code>format</code> 选码制。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/bar-code" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/bar-code.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/bar-code" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/bar-code" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/bar-code.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>给 value 就画码，缺省 Code 128，任意 ASCII 都收；人读文字印在条下</p>',4)),e(o,{src:"bar-code/01-basic"}),d[4]||(d[4]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;bar-code&quot;</code>：<strong><code>root</code></strong></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="码制" tabindex="-1">码制 <a class="header-anchor" href="#码制" aria-label="Permalink to &quot;码制&quot;">​</a></h3><p>零售商品用 EAN / UPC，外箱用 ITF-14，工业标签用 Code 39；定长数字码制的校验位可省，组件补上</p>',6)),e(o,{src:"bar-code/02-format"}),d[5]||(d[5]=t("h3",{id:"gs1-128",tabindex:"-1"},[a("GS1-128 "),t("a",{class:"header-anchor",href:"#gs1-128","aria-label":'Permalink to "GS1-128"'},"​")],-1)),d[6]||(d[6]=t("p",null,"gs1 打开后起始符后放 FNC1；定长 AI 直接连写，变长 AI 后面用 GS（U+001D）隔开下一个",-1)),e(o,{src:"bar-code/03-gs1"}),d[7]||(d[7]=t("h3",{id:"尺寸与静区",tabindex:"-1"},[a("尺寸与静区 "),t("a",{class:"header-anchor",href:"#尺寸与静区","aria-label":'Permalink to "尺寸与静区"'},"​")],-1)),d[8]||(d[8]=t("p",null,"barWidth 是最窄条的像素宽，整张码等比放大；height 只改条高；margin 是两侧静区的模块数",-1)),e(o,{src:"bar-code/04-size"}),d[9]||(d[9]=t("h3",{id:"人读文字",tabindex:"-1"},[a("人读文字 "),t("a",{class:"header-anchor",href:"#人读文字","aria-label":'Permalink to "人读文字"'},"​")],-1)),d[10]||(d[10]=t("p",null,"text 关掉只剩条；EAN 的守卫条照规范比数据条长 5X，不随文字走",-1)),e(o,{src:"bar-code/05-text"}),d[11]||(d[11]=t("h3",{id:"换色",tabindex:"-1"},[a("换色 "),t("a",{class:"header-anchor",href:"#换色","aria-label":'Permalink to "换色"'},"​")],-1)),d[12]||(d[12]=t("p",null,"颜色不是 props，写两个 CSS 变量即可：条必须比底色深且对比要足，反相码扫不出来",-1)),e(o,{src:"bar-code/06-color"}),d[13]||(d[13]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>货号、运单号、序列号要让扫描枪一枪读出。</li><li>商品零售码（EAN / UPC）、外箱码（ITF-14）、GS1 物流标签（GS1-128）。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>内容超过几十个字符、或含非 ASCII：一维码会拉得很长，改用<a href="./matrix-code">二维码</a>。</li><li>用户就在这台设备上：给一条可点的链接或可复制的文本。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>format</code> 七种码制：<code>code128</code>（缺省）、<code>ean13</code> / <code>ean8</code> / <code>upca</code> / <code>upce</code>、<code>itf14</code>、<code>code39</code>；给了不认识的值不画码，根落到 error 态。</li><li>定长数字码制收不带校验位的长度（补上）与带校验位的长度（核对），对不上就不画。</li><li><code>gs1</code> 把 Code 128 变成 GS1-128：起始符后放 FNC1，内容里的 GS（U+001D）编成变长 AI 之间的分隔。</li><li><code>text</code> 控制条下的人读文字；EAN / UPC 的数字逐位落在自己那格下面，守卫条按规范延长。</li><li><code>barWidth</code> 是最窄条的像素宽，整张码等比放大；<code>height</code> 是条高；<code>margin</code> 是静区，缺省按码制的规范值。</li><li><code>itf14</code> 缺省带上下承载条；<code>code39</code> 可选 mod 43 校验字符。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>外面套<a href="./card">卡片</a>；旁边配<a href="./clipboard">剪贴板</a>给出文本形式的同一内容。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>静区不能省，贴边的条码扫不出来；缺省值就是规范值，非要压缩也别低于码制要求。</li><li>屏幕上 <code>barWidth</code> 至少 2：1 像素宽的条在缩放过的屏幕上会糊成灰。</li><li>旁边同时给出文本：不是所有人都能扫。</li><li>内容里有小写或标点就用 <code>code128</code>；<code>code39</code> 只认大写字母、数字与七个符号。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>深色主题下直接反色：读码器按深条浅底取样，反相码扫不出来。</li><li>用 <code>height</code> 把条压得很矮：扫描线一歪就出了条的范围。</li><li>把校验位自己算错再传进来：组件会拒画，直接传不带校验位的长度让它补。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-bar-code&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhBarCode</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/bar-code.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>barWidth</code></td><td><code>number</code></td><td></td><td>最窄条的像素宽（X 尺寸），缺省 2；整张码的宽度由它乘模块数得出。</td></tr><tr><td><code>bearerBars</code></td><td><code>boolean</code></td><td></td><td>上下承载条：itf14 印在瓦楞纸上防止短读的两根横条，缺省画； 只对 itf14 有意义，给别的码制会往诊断通道报一条警告，按没给处理。</td></tr><tr><td><code>checksum</code></td><td><code>boolean</code></td><td></td><td>附 mod 43 校验字符。只对 code39 有意义——其余码制的校验位是规范必带的， 给了会往诊断通道报一条警告，按没给处理。</td></tr><tr><td><code>format</code></td><td><code>BarCodeFormat</code></td><td></td><td>码制，缺省 code128。给了不认识的值不画码，根落到 <code>error</code> 态。</td></tr><tr><td><code>gs1</code></td><td><code>boolean</code></td><td></td><td>GS1-128：起始符后放 FNC1，内容里的 GS（U+001D）编成变长 AI 之间的分隔。 只对 code128 有意义，给别的码制会往诊断通道报一条警告，按没给处理。</td></tr><tr><td><code>height</code></td><td><code>number</code></td><td></td><td>条的像素高，缺省 64；不含守卫条的延长段、人读文字与承载条。</td></tr><tr><td><code>label</code></td><td><code>string</code></td><td></td><td>可及名字，缺省用 value；给了全空白的名字等于没给。</td></tr><tr><td><code>margin</code></td><td><code>number</code></td><td></td><td>两侧静区，单位是模块数；缺省按码制的规范值（code128 / itf14 / code39 10，ean13 11，upca / upce 9，ean8 7）。</td></tr><tr><td><code>text</code></td><td><code>boolean</code></td><td></td><td>条下面是否印人读文字，缺省印。</td></tr><tr><td><code>value</code></td><td><code>string</code></td><td></td><td>要编码的内容；空串不画码。定长数字码制收不带或带校验位的两种长度，带了就核对。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;empty&#39;</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>format</code></td><td><code>BarCodeFormat</code></td><td>解析后的码制。给了不认识的值时保持原样透出，好让错误信息与 data-format 都指着那个值。</td></tr><tr><td><code>runs</code></td><td><code>readonly number[]</code></td><td>条空交替的宽度（模块），首元素是条；没画出码时是空数组。</td></tr><tr><td><code>modules</code></td><td><code>number</code></td><td>不含静区的模块数；没画出码时为 0。</td></tr><tr><td><code>encoded</code></td><td><code>string</code></td><td>实际编进码里的内容，含补上的校验位；没画出码时是空串。</td></tr><tr><td><code>margin</code></td><td><code>number</code></td><td>解析后的静区宽度，单位是模块数。</td></tr><tr><td><code>pixelWidth</code></td><td><code>number</code></td><td>根的像素宽高，也是 viewBox 的尺寸。</td></tr><tr><td><code>pixelHeight</code></td><td><code>number</code></td><td></td></tr><tr><td><code>viewBox</code></td><td><code>string</code></td><td>根的 viewBox。</td></tr><tr><td><code>path</code></td><td><code>string</code></td><td>全部条（含守卫条的延长段与承载条）合成的那条 <code>&amp;lt;path&amp;gt;</code> 的 d；没画出码时是空串，此时不该生成 path 节点。</td></tr><tr><td><code>text</code></td><td><code>readonly BarCodeTextRun[]</code></td><td>人读文字，每段一个 <code>&amp;lt;text&amp;gt;</code>；关了 <code>text</code> 或没画出码时是空数组。</td></tr><tr><td><code>fontSize</code></td><td><code>number</code></td><td>人读文字的字号，像素。</td></tr><tr><td><code>state</code></td><td><code>BarCodeState</code></td><td>当前状态。</td></tr><tr><td><code>error</code></td><td><code>string | undefined</code></td><td>编码失败的原因；其余状态为 undefined。</td></tr><tr><td><code>label</code></td><td><code>string | undefined</code></td><td>解析后的可及名字；没给名字时为 undefined，此时根退出无障碍树。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/practices/names-and-descriptions/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>root</code></td><td><code>aria-label</code></td><td>undefined | props.label</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>undefined | &#39;img&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/bar-code.css</code> 使用 <code>[data-scope=&quot;bar-code&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-format</code></td><td>props.format</td></tr><tr><td><code>root</code></td><td><code>data-modules</code></td><td>undefined | String(modules)</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;empty&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-bar-code-bg</code></td><td><code>root</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-color-neutral-0</code></td><td>bar-code 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-bar-code-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-color-neutral-950</code></td><td>bar-code 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-bar-code-font-family</code></td><td><code>root</code></td><td><code>font-family</code></td><td><code>xh-geom=text</code></td><td><code>--xh-font-family-mono</code></td><td>bar-code 的 root 部件 font-family 覆盖槽。</td></tr><tr><td><code>--xh-bar-code-placeholder-bg</code></td><td><code>root</code></td><td><code>background</code></td><td><code>state=empty</code><br><code>state=error</code></td><td><code>--xh-bg-subtle</code></td><td>bar-code 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-bar-code-placeholder-border</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>state=empty</code><br><code>state=error</code></td><td><code>--xh-border-default</code></td><td>bar-code 的 root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-bar-code-radius</code></td><td><code>root</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>bar-code 的 root 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-bar-code-text-fg</code></td><td><code>root</code></td><td><code>fill</code></td><td><code>xh-geom=text</code></td><td><code>currentColor</code></td><td>bar-code 的 root 部件 fill 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>background</code> · <code>box-shadow</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p>',43))])}const P=l(s,[["render",u]]);export{k as __pageData,P as default};
